INSERT INTO `notice` (`id`, `purpose`, `version`, `wording`, `published_by`, `published_at`) VALUES
	('notice-reply-2', 'reply', 2, 'NAISEMA keeps what you send on this form, with your name and email address, so that we can read it and reply to you. Only NAISEMA staff see it, and it is never published. We delete it 12 months after we have dealt with it, or sooner if you ask. You can withdraw this agreement at any time with the link in the email we send you, and ask to see or delete what we hold through our Privacy page.', NULL, 1791244800000),
	('notice-consultation-2', 'consultation', 2, 'NAISEMA may email you to invite you to take part in its consultations, in the ways you have chosen. Taking part is always your choice. We keep your details for this until you withdraw, and what you tell us in a consultation for 12 months after we have analysed it. You can withdraw at any time with the link in the email we send you.', NULL, 1791244800000),
	('notice-newsletter-2', 'newsletter', 2, 'NAISEMA will add your email address to its newsletter list, which is kept by an outside newsletter service. The service will email you first to check you want the newsletter, and nothing is sent unless you confirm. Every newsletter has a link to unsubscribe, and you can also unsubscribe on our Newsletter page at any time.', NULL, 1791244800000);
